DROP TABLE IF EXISTS `BIZ_CALENDAR_EXCLUSION`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_CALENDAR_EXCLUSION` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `SCOPE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'school' COMMENT '作用域(school/org)',
  `SCOPE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '作用域对象ID',
  `EXCLUSION_DATE` date NOT NULL COMMENT '排除日期',
  `REASON` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '排除原因',
  `CREATED_BY` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人ID',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BIZ_CAL_EXCL` (`SCOPE`,`SCOPE_ID`,`EXCLUSION_DATE`),
  KEY `IDX_BIZ_CAL_DATE` (`EXCLUSION_DATE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='校历排除日期';
