DROP TABLE IF EXISTS `BIZ_CHANGE_REQUEST`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_CHANGE_REQUEST` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `REQUESTER_USER_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人用户ID',
  `TARGET_TYPE` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '变更目标类型(class/org/course_binding等)',
  `TARGET_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '目标ID',
  `CHANGE_JSON` longtext COLLATE utf8mb4_general_ci NOT NULL COMMENT '变更内容JSON',
  `REASON` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请理由',
