DROP TABLE IF EXISTS `BIZ_DAILY_RECORD`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_DAILY_RECORD` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `RECORD_DATE` date NOT NULL COMMENT '记录日期',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `ORG_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学院ID',
  `COURSE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '课程ID',
  `ATTENDANCE_STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '出勤状态',
  `HOMEWORK_STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '作业状态',
  `CLASS_BEHAVIOR` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '课堂表现',
  `REMARKS` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `SOURCE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '记录来源',
  `APPROVED_STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '审核状态',
  `APPROVED_BY` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核人ID',
  `APPROVED_AT` datetime DEFAULT NULL COMMENT '审核时间',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BIZ_DR_STU_DATE_COURSE` (`STUDENT_ID`,`RECORD_DATE`,`COURSE_ID`),
  KEY `IDX_BIZ_DR_CLASS_DATE` (`CLASS_ID`,`RECORD_DATE`),
  KEY `IDX_BIZ_DR_ORG_DATE` (`ORG_ID`,`RECORD_DATE`),
  KEY `IDX_BIZ_DR_STU_DATE` (`STUDENT_ID`,`RECORD_DATE`),
  KEY `IDX_BIZ_DR_COMP` (`STUDENT_ID`,`ATTENDANCE_STATUS`,`RECORD_DATE`,`COURSE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学生每日考勤与表现记录';
