--
-- Table structure for table `BIZ_GRADE`
--

DROP TABLE IF EXISTS `BIZ_GRADE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_GRADE` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `COURSE_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程ID',
  `TERM_CODE` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学期编码',
  `SCORE` decimal(6,2) DEFAULT NULL COMMENT '成绩分数',
  `GRADE_POINT` decimal(4,2) DEFAULT NULL COMMENT '绩点',
  `PASS_STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'unknown' COMMENT '及格状态(pass/fail/unknown)',
  `SOURCE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'import' COMMENT '数据来源',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BIZ_GRADE_STU_COURSE_TERM` (`STUDENT_ID`,`COURSE_ID`,`TERM_CODE`),
  KEY `IDX_BIZ_GRADE_TERM` (`TERM_CODE`),
  KEY `IDX_BIZ_GRADE_STU` (`STUDENT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学生成绩';
/*!40101 SET character_set_client = @saved_cs_client */;

