-- Table structure for table `BIZ_LEAVE_REQUEST`
--

DROP TABLE IF EXISTS `BIZ_LEAVE_REQUEST`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_LEAVE_REQUEST` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `FROM_DATE` datetime NOT NULL COMMENT '请假开始时间',
  `TO_DATE` datetime NOT NULL COMMENT '请假结束时间',
  `REASON` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '请假原因',
  `PROOF_FILE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主凭证文件ID',
  `PROOF_FILE_IDS_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '多凭证文件ID列表JSON',
  `STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'submitted' COMMENT '审批状态(submitted/approved/rejected)',
  `APPROVER_USER_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审批人ID',
  `APPROVED_AT` datetime DEFAULT NULL COMMENT '通过时间',
  `REJECTED_AT` datetime DEFAULT NULL COMMENT '驳回时间',
