--
-- Table structure for table `BIZ_NOTIFICATION_JOB`
--

DROP TABLE IF EXISTS `BIZ_NOTIFICATION_JOB`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_NOTIFICATION_JOB` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `TRIGGER_TYPE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '触发方式(auto/manual)',
  `WARNING_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联预警ID',
  `SENDER_USER_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发送人ID',
  `CHANNEL` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送渠道(email/sms/inbox)',
  `TEMPLATE_CODE` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '模板编码',
  `RECEIVERS_JSON` longtext COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收者列表JSON',
  `PARAMS_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '模板参数JSON',
  `SCHEDULE_AT` datetime DEFAULT NULL COMMENT '计划发送时间',
  `COOLDOWN_KEY` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '冷却去重键',
  `STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务状态(queued/sent/failed/cancelled)',
  `TRY_COUNT` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `LAST_ERROR` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '最近错误信息',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_NJ_STATUS_TIME` (`STATUS`,`CREATE_TIME`),
  KEY `IDX_BIZ_NJ_STATUS_SCHED` (`STATUS`,`SCHEDULE_AT`),
  KEY `IDX_BIZ_NJ_WARN_CH` (`WARNING_ID`,`CHANNEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='异步通知发送任务';
