--
-- Table structure for table `BIZ_NOTIFICATION_LOG`
--

DROP TABLE IF EXISTS `BIZ_NOTIFICATION_LOG`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_NOTIFICATION_LOG` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `JOB_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '通知任务ID',
  `CHANNEL` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送渠道',
  `RECEIVER` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收地址',
  `CONTENT_SNAPSHOT` longtext COLLATE utf8mb4_general_ci COMMENT '发送内容快照',
  `SEND_STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送状态',
  `PROVIDER` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '通道服务商',
  `PROVIDER_MSG_ID` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '服务商回执ID',
  `ERROR_MSG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '失败原因',
  `SENT_AT` datetime NOT NULL COMMENT '发送时间',
  `ACKNOWLEDGED` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已确认(1是/0否)',
  `ACKNOWLEDGED_AT` datetime DEFAULT NULL COMMENT '确认时间',
  `ACKNOWLEDGED_BY` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '确认人ID',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_NL_JOB` (`JOB_ID`),
  KEY `IDX_BIZ_NL_SENT` (`SENT_AT`),
  KEY `IDX_BIZ_NL_STATUS_SENT` (`SEND_STATUS`,`SENT_AT`),
  KEY `IDX_BIZ_NL_CH_SENT` (`CHANNEL`,`SENT_AT`),
  KEY `IDX_BIZ_NL_RCV_SENT` (`RECEIVER`(64),`SENT_AT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='通知发送明细日志';
/*!40101 SET character_set_client = @saved_cs_client */;

