--
-- Table structure for table `BIZ_SCHEDULE`
--

DROP TABLE IF EXISTS `BIZ_SCHEDULE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_SCHEDULE` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `TERM_CODE` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学期编码',
  `COURSE_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `TEACHER_USER_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '任课教师ID',
  `SESSION_START` datetime NOT NULL COMMENT '上课开始时间',
  `SESSION_END` datetime NOT NULL COMMENT '上课结束时间',
  `EXPIRE_MINUTES` int NOT NULL DEFAULT '15' COMMENT '签到有效分钟数',
  `STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '状态(active/inactive)',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_SCHED_CLASS_START` (`CLASS_ID`,`SESSION_START`),
  KEY `IDX_BIZ_SCHED_TERM` (`TERM_CODE`),
  KEY `IDX_BIZ_SCHED_STATUS` (`STATUS`),
  KEY `IDX_BIZ_SCHED_COURSE` (`COURSE_ID`),
  KEY `IDX_BIZ_SCHED_TEACHER` (`TEACHER_USER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='排课课表';
/*!40101 SET character_set_client = @saved_cs_client */;

