-- Table structure for table `BIZ_STUDENT_PROFILE`
--

DROP TABLE IF EXISTS `BIZ_STUDENT_PROFILE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_STUDENT_PROFILE` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `CLIENT_USER_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'C端用户ID',
  `STUDENT_NO` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学号',
  `NAME` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '学生姓名',
  `GENDER` varchar(8) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '性别',
  `PHOTO_FILE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '证件照文件ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属班级ID',
  `ORG_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属学院ID',
  `MAJOR_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '专业ID',
  `MAJOR` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '专业名称',
  `ENROLL_YEAR` int DEFAULT NULL COMMENT '入学年份',
  `MOBILE` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号(SM4加密)',
  `EMAIL` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `EMERGENCY_CONTACT_NAME` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '紧急联系人姓名',
  `EMERGENCY_CONTACT_MOBILE` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '紧急联系人手机(SM4加密)',
  `NOTIFY_PREFS_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '通知偏好配置JSON',
  `STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '学籍状态(active/inactive/graduated)',
  `INITIAL_PASSWORD` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '初始密码密文',
  `STUDENT_POSITION` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '学生职务',
  `WX_OPENID` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信OpenID',
  `WX_UNIONID` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信UnionID',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BIZ_SP_CLIENT_USER` (`CLIENT_USER_ID`),
  UNIQUE KEY `UK_BIZ_SP_STUDENT_NO` (`STUDENT_NO`),
  KEY `IDX_BIZ_SP_CLASS_STATUS_NO` (`CLASS_ID`,`STATUS`,`STUDENT_NO`),
  KEY `IDX_BIZ_SP_ORG` (`ORG_ID`),
  KEY `IDX_BIZ_SP_MAJOR` (`MAJOR_ID`),
  KEY `IDX_BIZ_SP_STATUS` (`STATUS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学生档案';
/*!40101 SET character_set_client = @saved_cs_client */;

