--
-- Table structure for table `BIZ_STUDENT_WARNING_SNAPSHOT`
--

DROP TABLE IF EXISTS `BIZ_STUDENT_WARNING_SNAPSHOT`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_STUDENT_WARNING_SNAPSHOT` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `ORG_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学院ID',
  `TODAY_WARNING_TOTAL` int NOT NULL DEFAULT '0' COMMENT '今日预警数',
  `WEEK_WARNING_TOTAL` int NOT NULL DEFAULT '0' COMMENT '本周预警数',
  `MONTH_WARNING_TOTAL` int NOT NULL DEFAULT '0' COMMENT '本月预警数',
  `ACTIVE_WARNING_COUNT` int NOT NULL DEFAULT '0' COMMENT '活跃预警数',
  `CLOSED_WARNING_COUNT` int NOT NULL DEFAULT '0' COMMENT '已关闭预警数',
  `ALL_WARNING_COUNT` int NOT NULL DEFAULT '0' COMMENT '累计预警总数',
  `ACTIVE_HIGHEST_LEVEL` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '当前最高等级',
  `CLOSED_HIGHEST_LEVEL` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '历史最高等级',
  `ALL_HIGHEST_LEVEL` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '全部最高等级',
  `ACTIVE_LAST_WARNING_AT` datetime DEFAULT NULL COMMENT '最近活跃预警时间',
  `CLOSED_LAST_WARNING_AT` datetime DEFAULT NULL COMMENT '最近关闭预警时间',
  `ALL_LAST_WARNING_AT` datetime DEFAULT NULL COMMENT '最近预警时间',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BIZ_SWS_STUDENT` (`STUDENT_ID`),
  KEY `IDX_BIZ_SWS_CLASS` (`CLASS_ID`),
  KEY `IDX_BIZ_SWS_ORG` (`ORG_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学生预警统计快照';
/*!40101 SET character_set_client = @saved_cs_client */;

