--
-- Table structure for table `BIZ_WARNING`
--

DROP TABLE IF EXISTS `BIZ_WARNING`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_WARNING` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `ORG_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学院ID',
  `METRIC` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'absent' COMMENT '预警指标',
  `LEVEL` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警等级(yellow/orange/red/severe)',
  `WINDOW_TYPE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '统计窗口(daily/weekly/monthly/term)',
  `PERIOD_START` date NOT NULL COMMENT '周期开始日期',
  `PERIOD_END` date NOT NULL COMMENT '周期结束日期',
  `RULE_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则ID',
  `RULE_SNAPSHOT_JSON` longtext COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则快照JSON',
  `TRIGGER_SUMMARY` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '触发摘要',
  `TRIGGER_DETAIL_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '触发明细JSON',
  `COURSE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '课程ID',
  `STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警状态(open/acknowledged/closed)',
  `ACKNOWLEDGED_AT` datetime DEFAULT NULL COMMENT '学生确认时间',
  `ACKNOWLEDGED_BY` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '确认人ID',
  `CLOSED_AT` datetime DEFAULT NULL COMMENT '关闭时间',
  `CLOSED_BY` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关闭人ID',
  `CLOSE_NOTE` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关闭说明',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_WARN_STU_TIME` (`STUDENT_ID`,`CREATE_TIME`),
  KEY `IDX_BIZ_WARN_STU_STATUS` (`STUDENT_ID`,`STATUS`),
  KEY `IDX_BIZ_WARN_STU_LEVEL` (`STUDENT_ID`,`LEVEL`),
  KEY `IDX_BIZ_WARN_CLASS_STATUS` (`CLASS_ID`,`STATUS`),
  KEY `IDX_BIZ_WARN_ORG_LEVEL` (`ORG_ID`,`LEVEL`),
  KEY `IDX_BIZ_WARN_STATUS` (`STATUS`),
  KEY `IDX_BIZ_WARN_STATUS_COURSE` (`STATUS`,`COURSE_ID`,`CREATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学业预警历史记录';
/*!40101 SET character_set_client = @saved_cs_client */;

