--
-- Table structure for table `BIZ_WARNING_CASE`
--

DROP TABLE IF EXISTS `BIZ_WARNING_CASE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_WARNING_CASE` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `ORG_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学院ID',
  `PRIMARY_WARNING_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主预警ID',
  `SOURCE_WARNING_IDS_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '关联预警ID列表JSON',
  `RISK_SCORE` int NOT NULL DEFAULT '0' COMMENT '综合风险分',
  `RISK_BREAKDOWN_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '风险构成明细JSON',
  `WARNING_SUMMARY_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '预警摘要JSON',
  `HANDLING_PRIORITY` int NOT NULL DEFAULT '0' COMMENT '处置优先级',
  `STATUS` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending_assignment' COMMENT '工单状态',
  `HANDLER_USER_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '当前处置人ID',
  `ASSIGNED_BY` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '指派人ID',
  `ASSIGNED_AT` datetime DEFAULT NULL COMMENT '指派时间',
  `ACCEPTED_AT` datetime DEFAULT NULL COMMENT '接单时间',
  `COMPLETED_AT` datetime DEFAULT NULL COMMENT '完成时间',
  `RESOLVED_AT` datetime DEFAULT NULL COMMENT '结案时间',
  `COMPLETION_SUMMARY` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '处置结案摘要',
  `COMPLETION_DETAIL_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '处置详情JSON',
  `LATEST_WARNING_AT` datetime DEFAULT NULL COMMENT '最新预警时间',
  `LAST_RISK_AT` datetime DEFAULT NULL COMMENT '最近风险计算时间',
  `IS_ACTIVE` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否活跃(1是/0否)',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_WC_STU_ACTIVE` (`STUDENT_ID`,`IS_ACTIVE`),
  KEY `IDX_BIZ_WC_STATUS_ACTIVE` (`STATUS`,`IS_ACTIVE`),
  KEY `IDX_BIZ_WC_HANDLER_STATUS` (`HANDLER_USER_ID`,`STATUS`),
  KEY `IDX_BIZ_WC_CLASS_STATUS` (`CLASS_ID`,`STATUS`),
  KEY `IDX_BIZ_WC_ORG_STATUS` (`ORG_ID`,`STATUS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='高风险学生干预工单';
/*!40101 SET character_set_client = @saved_cs_client */;

