DROP TABLE IF EXISTS `BIZ_WARNING_CASE_LOG`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_WARNING_CASE_LOG` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `CASE_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '干预工单ID',
  `ACTION` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '动作编码',
  `ACTOR_USER_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作人ID',
  `NOTE` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '处理备注',
  `DETAIL_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '动作明细JSON',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_WCL_CASE_TIME` (`CASE_ID`,`CREATE_TIME`),
  KEY `IDX_BIZ_WCL_ACTOR_TIME` (`ACTOR_USER_ID`,`CREATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='高风险干预工单流转日志';
/*!40101 SET character_set_client = @saved_cs_client */;

