--
-- Table structure for table `BIZ_WARNING_CURRENT_STATE`
--

DROP TABLE IF EXISTS `BIZ_WARNING_CURRENT_STATE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_WARNING_CURRENT_STATE` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `STUDENT_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学生档案ID',
  `CLASS_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '班级ID',
  `ORG_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '学院ID',
  `METRIC` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警指标',
  `LEVEL` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警等级',
  `WINDOW_TYPE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '统计窗口',
  `PERIOD_START` date NOT NULL COMMENT '周期开始日期',
  `PERIOD_END` date NOT NULL COMMENT '周期结束日期',
  `COURSE_KEY` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '课程唯一键',
  `COURSE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '课程ID',
  `RULE_ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则ID',
  `RULE_SNAPSHOT_JSON` longtext COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则快照JSON',
  `TRIGGER_SUMMARY` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '触发摘要',
  `TRIGGER_DETAIL_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '触发明细JSON',
  `CURRENT_COUNT` int NOT NULL DEFAULT '0' COMMENT '当前累计次数',
  `STATUS` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态(open/acknowledged)',
  `ACKNOWLEDGED_AT` datetime DEFAULT NULL COMMENT '确认时间',
  `ACKNOWLEDGED_BY` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '确认人ID',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_BIZ_WCS_COURSE` (`STUDENT_ID`,`METRIC`,`WINDOW_TYPE`,`PERIOD_START`,`PERIOD_END`,`COURSE_KEY`),
  KEY `IDX_BIZ_WCS_STU_STATUS` (`STUDENT_ID`,`STATUS`),
  KEY `IDX_BIZ_WCS_CLASS_STATUS` (`CLASS_ID`,`STATUS`),
  KEY `IDX_BIZ_WCS_ORG_STATUS` (`ORG_ID`,`STATUS`),
  KEY `IDX_BIZ_WCS_ORG_LEVEL` (`ORG_ID`,`LEVEL`),
  KEY `IDX_BIZ_WCS_COURSE_STATUS` (`COURSE_ID`,`STATUS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学生当前实时预警状态';
/*!40101 SET character_set_client = @saved_cs_client */;

