DROP TABLE IF EXISTS `BIZ_WARNING_RULE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BIZ_WARNING_RULE` (
  `ID` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `SCOPE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'school' COMMENT '规则范围(school/college)',
  `SCOPE_ID` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '范围对象ID',
  `RULE_VERSION` int NOT NULL DEFAULT '1' COMMENT '规则版本号',
  `LEVEL` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预警等级(yellow/orange/red/severe)',
  `WINDOW_TYPE` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '统计窗口(daily/weekly/monthly/term)',
  `METRIC` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '统计指标',
  `THRESHOLD` int NOT NULL COMMENT '触发阈值',
  `ENABLED` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用(1启用/0停用)',
  `EXCLUSIONS_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '排除条件JSON',
  `NOTIFY_STRATEGY_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '通知策略JSON',
  `CREATED_BY` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人ID',
  `EXT_JSON` longtext COLLATE utf8mb4_general_ci COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) COLLATE utf8mb4_general_ci DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `IDX_BIZ_WR_SCOPE` (`SCOPE`,`SCOPE_ID`),
  KEY `IDX_BIZ_WR_LEVEL` (`LEVEL`),
  KEY `IDX_BIZ_WR_ENABLED` (`ENABLED`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='学业预警规则';
/*!40101 SET character_set_client = @saved_cs_client */;

